create table medical_schedule
(
    schedule_id  bigint auto_increment comment '排班ID'
        primary key,
    doctor_id    bigint                 not null comment '医生ID',
    work_date    date                   not null comment '出诊日期',
    period tinyint not null comment '时段：1上午 2下午 3晚间',
    start_time   time                   null comment '开始时间',
    end_time     time                   null comment '结束时间',
    total_slots  int         default 0  not null comment '总号源数',
    booked_slots int         default 0  null comment '已预约数',
    slot_minutes int         default 30 null comment '每个号源时长（分钟）',
    status       tinyint     default 0  null comment '状态：0正常 1停诊 2已满',
    create_by    varchar(64) default '' null comment '创建者',
    create_time  datetime               null comment '创建时间',
    update_by    varchar(64) default '' null comment '更新者',
    update_time  datetime               null comment '更新时间',
    remark       varchar(500)           null comment '备注',
    constraint uk_doctor_date_period
        unique (doctor_id, work_date, period)
)
    comment '医生排班号源表' charset = utf8mb4;

create index idx_work_date
    on medical_schedule (work_date);

